  const t = (inp.messageText || '').toLowerCase().trim();
  // Señales claras de inglés
  if (/\b(hello|hi there|good morning|good evening|yes please|thank you|i want|i need|i have|quote|schedule|compare|how much|can you|my name|i am|i'm|let's|let me|what is|please help)\b/.test(t)) return 'en';
  if (/^(hello|hi|hey|yes|yeah|nope|sure|ok cool|thanks|quote|schedule|compare|good)$/.test(t)) return 'en';
