// MongoDB: db.availability.find({ providerId, clinicId, date: { $gte: today } }).limit(5)
const mockGetSlots = (providerId, clinicId) => {
  const hash   = (providerId.charCodeAt(1) + (clinicId.charCodeAt(3) || 1)) % 3;
  const groups = [['09:00','10:30','14:00'],['09:30','11:00','15:00'],['10:00','14:30','16:00']];
  const times  = groups[hash];
  const dE=['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];
  const dX=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const dP=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
  const mo=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
  const slots = [];
  let d = new Date(); d.setDate(d.getDate() + 1);
  let added = 0;
  while (added < 3) {
    if (d.getDay() !== 0 && d.getDay() !== 6) {
      times.forEach(time => slots.push({
        id:   `sl_${providerId}_${d.toISOString().split('T')[0]}_${time.replace(':','')}`,
        date: d.toISOString().split('T')[0],
        time,
        dispEs: `${dE[d.getDay()]} ${d.getDate()} ${mo[d.getMonth()]} · ${time}`,
        dispEn: `${dX[d.getDay()]} ${mo[d.getMonth()]} ${d.getDate()} · ${time}`,
        dispPt: `${dP[d.getDay()]} ${d.getDate()} ${mo[d.getMonth()]} · ${time}`
      }));
      added++;
    }
    d = new Date(d); d.setDate(d.getDate() + 1);
  }
  return slots;
};

