const detectSpecialty = t => {
  const n = normalize(t);
  if (/dental|diente|muela|implant|ortodoncia|corona|veneer|blanquea|endodoncia|conducto|tooth|teeth|braces|dente|ortodon|implantol|periodont/.test(n)) return 'dental';
  if (/plastic|rinoplas|liposu|mamario|busto|bichec|blefaroplas|lifting|bbl|nariz|estetica|estetic|facial|corporal|abdominoplas|otoplas/.test(n)) return 'plastic_surgery';
  if (/^1$/.test(n.trim())) return 'dental';
  if (/^2$/.test(n.trim())) return 'plastic_surgery';
  return null;
};

const detectModality = t => {
  const n = normalize(t);
  if (/presencial|person|clinic|clinica|^1$/.test(n)) return 'presencial';
  if (/video|virtual|remoto|online|tele|^2$/.test(n)) return 'video';
  return null;
};

